"""Temperature conversions between Celsius (C), Fahrenheit (F), and kelvin (K)."""


def to_kelvin(value: float, unit: str) -> float:
    """A temperature in C, F, or K, expressed in kelvin."""
    if unit == "C":
        return value + 273.15
    if unit == "F":
        return (value - 32) * 5 / 9 + 273.15
    if unit == "K":
        return value
    raise ValueError(f"unknown temperature unit: {unit}")


def from_kelvin(value: float, unit: str) -> float:
    """A temperature in kelvin, expressed in C, F, or K."""
    if unit == "C":
        return value - 273.15
    if unit == "F":
        return (value - 273.15) * 9 / 5 + 32
    if unit == "K":
        return value
    raise ValueError(f"unknown temperature unit: {unit}")


def convert_temperature(value: float, src: str, dst: str) -> float:
    """Convert a temperature from unit src to unit dst."""
    return round(from_kelvin(to_kelvin(value, src), dst), 2)

