import pytest

from unitconv.scales import convert_length, convert_mass


def test_km_to_m():
    assert convert_length(2, "km", "m") == 2000


def test_inch_to_cm():
    assert convert_length(1, "in", "cm") == pytest.approx(2.54)


def test_kg_to_lb():
    assert convert_mass(1, "kg", "lb") == pytest.approx(2.20462, rel=1e-5)


def test_unknown_unit():
    with pytest.raises(ValueError):
        convert_length(1, "furlong", "m")

